	got["prod"] = imagesearch.Outcome{Verdict: imagesearch.VerdictFailed}
	if o, _ := verdictOf(t, m, "prod"); o.Verdict != imagesearch.VerdictOK {
		t.Error("RegistryBrowserOutcomes returned the live map, not a copy")
	}
}

